window.ScripturaLexicons = window.ScripturaLexicons || {};
window.ScripturaLexicons.BDAG_PART_0004 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agalliao-bdag\" data-source=\"BDAG\" data-search=\"ἀγαλλιάω agalliao exultar alegrar-se extremamente regozijar-se júbilo BDAG\" tabindex=\"0\">\n<td class=\"table-lemma greek\">ἀγαλλιάω</td><td>Verbo</td><td>exultar; regozijar-se; alegrar-se muito</td><td><span class=\"source-pill\">BDAG</span></td>\n</tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agallomai-bdag\" data-source=\"BDAG\" data-search=\"ἀγάλλομαι agallomai alegrar-se ter prazer BDAG\" tabindex=\"0\">\n<td class=\"table-lemma greek\">ἀγάλλομαι</td><td>Verbo</td><td>alegrar-se; ter prazer</td><td><span class=\"source-pill\">BDAG</span></td>\n</tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agamos-bdag\" data-source=\"BDAG\" data-search=\"ἄγαμος agamos solteiro não casado divorciada homem mulher 1 Coríntios BDAG\" tabindex=\"0\">\n<td class=\"table-lemma greek\">ἄγαμος</td><td>Adjetivo/Substantivo</td><td>não casado; solteiro</td><td><span class=\"source-pill\">BDAG</span></td>\n</tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aganakteo-bdag\" data-source=\"BDAG\" data-search=\"ἀγανακτέω aganakteo indignar-se irritar-se zangar-se ira Mateus Marcos Lucas BDAG\" tabindex=\"0\">\n<td class=\"table-lemma greek\">ἀγανακτέω</td><td>Verbo</td><td>indignar-se; irritar-se; zangar-se</td><td><span class=\"source-pill\">BDAG</span></td>\n</tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aganaktesis-bdag\" data-source=\"BDAG\" data-search=\"ἀγανάκτησις aganaktesis indignação 2 Coríntios BDAG\" tabindex=\"0\">\n<td class=\"table-lemma greek\">ἀγανάκτησις</td><td>Substantivo</td><td>indignação</td><td><span class=\"source-pill\">BDAG</span></td>\n</tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agapao-bdag\" data-source=\"BDAG\" data-search=\"ἀγαπάω agapao amar estimar ter afeição prezar ter prazer demonstrar amor Deus Cristo próximo inimigo BDAG\" tabindex=\"0\">\n<td class=\"table-lemma greek\">ἀγαπάω</td><td>Verbo</td><td>amar; estimar; ter afeição; ter prazer</td><td><span class=\"source-pill\">BDAG</span></td>\n</tr>", cardsHtml:"<article id=\"entry-agalliao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\">\n<div><h1 class=\"entry-title greek\">ἀγαλλιάω</h1>\n<div class=\"entry-meta\"><span class=\"transliteration\">⟦agalliáō⟧</span><span class=\"separator\">·</span><span>verbo</span></div>\n</div><div class=\"source-tag\">BDAG</div>\n</header>\n<div class=\"entry-divider\"></div>\n<section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"> (Formação nova no grego helenístico a partir de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάλλω\" data-meanings=\"glorificar|exultar\">ἀγάλλω</span>, encontrada somente em escritores bíblicos e eclesiásticos.) Raramente ativo (<span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B-D-F §101\" data-tooltip-text=\"Blass-Debrunner-Funk, §101\">B-D-F §101</span>; Mlt.-H. 225 s.):\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαλλιᾶτε\" data-meanings=\"exultai\">ἀγαλλιᾶτε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1.8</a> v.l. (por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαλλιᾶσθε\" data-meanings=\"exultais|regozijai-vos\">ἀγαλλιᾶσθε</span>);\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 19.7</a> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαλλιῶμεν\" data-meanings=\"exultemos\">ἀγαλλιῶμεν</span> (v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαλλιώμεθα\" data-meanings=\"regozijemo-nos\">ἀγαλλιώμεθα</span>);\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαλλιῶντα\" data-meanings=\"exultando\">ἀγαλλιῶντα</span> GJs 17:2;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαλλιῶντες\" data-meanings=\"exultando\">ἀγαλλιῶντες</span> ApcPt Rainer. 1º aoristo (como POxy 1592, 4 [séc. IV d.C.]) <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαλλίασεν\" data-meanings=\"exultou\">ἠγαλλίασεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.47</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπὶ τ. θεῷ\" data-meanings=\"em Deus|por causa de Deus\">ἐπὶ τ. θεῷ</span>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/HAB.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hc 3.18</a> v.l.); usualmente depoente <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαλλιάομαι\" data-meanings=\"exultar|regozijar-se\">ἀγαλλιάομαι</span> (Syntipas p. 75, 28); futuro <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαλλιάσομαι\" data-meanings=\"exultarei\">ἀγαλλιάσομαι</span> (LXX); 1º aoristo médio <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαλλιασάμην\" data-meanings=\"exultei\">ἠγαλλιασάμην</span> ou passivo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαλλιάθην\" data-meanings=\"exultei|fui tomado de júbilo\">ἠγαλλιάθην</span> (v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαλλιάσθην\" data-meanings=\"exultei\">ἠγαλλιάσθην</span>; <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B-D-F §78\" data-tooltip-text=\"Blass-Debrunner-Funk, §78\">B-D-F §78</span>; Mlt.-H. 225):\n<strong>estar extremamente alegre, exultar, alegrar-se, ficar jubiloso</strong> (LXX; En 104:13; TestSol 19:1 P; TestAbr A 7 p. 84, 2 s. [Stone p. 16]; TestJob; ParJer 6:20; ApcrEzk P 1 recto 1; Test12Patr; Mel., <em>P.</em> 80, 586). Absoluto: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1.6</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαλλιάσαντες\" data-meanings=\"tendo exultado\">ἀγαλλιάσαντες</span> P72);\n<span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"1 Cl 18:8\" data-tooltip-text=\"Primeira Epístola de Clemente 18.8\">1 Cl 18:8</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.50.10\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 50.10</a>); IMg 1:1; Hm 5, 1, 2; 5, 2, 3; Hs 1:6; MPol 19:2; GJs 17:2; ApcPt Rainer. “Minha língua exulta” <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.26</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 15.9</a>); como aqui, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εὐφραίνεσθαι\" data-meanings=\"alegrar-se|regozijar-se\">εὐφραίνεσθαι</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.30.8\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 30.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.31.11\" target=\"_blank\" rel=\"noopener noreferrer\">31.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.25.9\" target=\"_blank\" rel=\"noopener noreferrer\">Is 25.9</a>) Hm 5, 1, 2; Hs 9, 18, 4;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"χαίρειν καὶ ἀ.\" data-meanings=\"alegrar-se e exultar\">χαίρειν καὶ ἀ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 13.15</a> BA; TestJob 43:15)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 19.7</a>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα χαρῆτε ἀγαλλιώμενοι\" data-meanings=\"para que vos alegreis exultando\">ἵνα χαρῆτε ἀγαλλιώμενοι</span>, <em>para que griteis de alegria</em>,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 4.13</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαλλιώμενοι προσηύχοντο\" data-meanings=\"exultando, oravam\">ἀγαλλιώμενοι προσηύχοντο</span> AcPl Ha 1, 32;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαλλιώμενος ἐσκίρτησεν\" data-meanings=\"exultando, saltou\">ἀγαλλιώμενος ἐσκίρτησεν</span> 3, 17;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. … καὶ κλαίειν\" data-meanings=\"exultar … e chorar\">ἀ. … καὶ κλαίειν</span>, <em>chorar de alegria</em>, 6, 2. Com particípio complementar (<span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B-D-F §415\" data-tooltip-text=\"Blass-Debrunner-Funk, §415\">B-D-F §415</span>):\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαλλιάσατο πεπιστευκώς\" data-meanings=\"exultou por ter crido\">ἠγαλλιάσατο πεπιστευκώς</span>,\n<em>ficou muito alegre porque se tornara crente</em>,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 16.34</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαλλιάσοντο μεγάλως μηνύ̣[οντες]\" data-meanings=\"exultavam grandemente ao anunciar\">ἠγαλλιάσοντο μεγάλως μηνύ̣[οντες]</span> AcPl Ha 8, 5 (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαλλι[ᾶτο] μηνύων\" data-meanings=\"exultava ao anunciar\">ἠγαλλι[ᾶτο] μηνύων</span> BMM recto 3 s.). Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα\" data-meanings=\"para que|que\">ἵνα</span> em seguida (veja ἵνα 2aα):\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ., ἵνα ἴδῃ\" data-meanings=\"exultou para que visse|exultou porque veria\">ἀ., ἵνα ἴδῃ</span>,\n<em>ficou jubiloso por haver de ver</em>,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.56\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.56</a> (<span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B-D-F §392, 1\" data-tooltip-text=\"Blass-Debrunner-Funk, §392, 1\">B-D-F §392, 1</span>). Aquele que causa a alegria é dado no dativo:\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. τῷ πνεύματι τῷ ἁγίῳ\" data-meanings=\"exultar no Espírito Santo\">ἀ. τῷ πνεύματι τῷ ἁγίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10.21</a> v.l.; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν\" data-meanings=\"em\">ἐν</span> e dativo, ibid. — Com dativo de causa:\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. χαρᾷ ἀνεκλαλήτῳ\" data-meanings=\"exultar com alegria inexprimível\">ἀ. χαρᾷ ἀνεκλαλήτῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1.8</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἷς ἀγαλλιῶμαι\" data-meanings=\"nisso me alegro\">οἷς ἀγαλλιῶμαι</span>, <em>nisso me regozijo</em>, IEph 9:2 (compare Quinto de Esmirna 9, 118 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παισὶν ἀγαλλόμενος\" data-meanings=\"exultando em voz alta por seus filhos\">παισὶν ἀγαλλόμενος</span>). O objeto da alegria é indicado por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπί τινι\" data-meanings=\"por algo|em algo\">ἐπί τινι</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 9.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.20.2\" target=\"_blank\" rel=\"noopener noreferrer\">20.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.30.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 30.3</a>, entre outros; <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B-D-F §196\" data-tooltip-text=\"Blass-Debrunner-Funk, §196\">B-D-F §196</span>): 1 Cl 33:2; Hs 8, 1, 18; 9, 24, 2. Também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔν τινι\" data-meanings=\"em algo\">ἔν τινι</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.88.17\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 88.17</a>)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.35</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ἐν τῷ πάθει\" data-meanings=\"regozijar-se na Paixão\">ἀ. ἐν τῷ πάθει</span> IPhld ins. O acusativo ocorre uma vez:\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. τὴν δικαιοσύνην\" data-meanings=\"regozijar-se na justiça\">ἀ. τὴν δικαιοσύνην</span> <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"1 Cl 18:15\" data-tooltip-text=\"Primeira Epístola de Clemente 18.15\">1 Cl 18:15</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.50.16\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 50.16</a>). — <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"[ἀγαλ]λ[ι]ῶσιν\" data-meanings=\"[exultam]\">[ἀγαλ]λ[ι]ῶσιν</span> é uma restauração provável em AcPl BMM verso 20 s. — Goodsp., <em>Probs.</em> 192–194; W. Nauck, “Freude im Leiden”, <em>ZNW</em> 46, 1955, 68–80. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάλλομαι\" data-meanings=\"alegrar-se|ter prazer\">ἀγάλλομαι</span>. <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"TW\" data-tooltip-text=\"Theologisches Wörterbuch zum Neuen Testament\">TW</span>.\n</p>\n</section>\n</article><article id=\"entry-agallomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\">\n<div><h1 class=\"entry-title greek\">ἀγάλλομαι</h1>\n<div class=\"entry-meta\"><span class=\"transliteration\">⟦agállomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div>\n</div><div class=\"source-tag\">BDAG</div>\n</header>\n<div class=\"entry-divider\"></div>\n<section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"> (Homero em diante;\n<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0526.tlg001.perseus-grc1%3A18.66\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Jos., Ant. 18, 66\" data-tooltip-text=\"Flávio Josefo, Antiguidades Judaicas 18.66 — texto grego original no Perseus Digital Library; destino validado\">Jos., Ant. 18, 66</a>; SibOr 3, 785; TestAbr A 11 p. 89, 17 [Stone p. 26], entre outros; ParJer 6:6 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάλλου\" data-meanings=\"alegra-te|regozija-te\">ἀγάλλου</span>.)\n<strong>Alegrar-se, ter prazer</strong>,\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπί τινι\" data-meanings=\"em algo|por algo\">ἐπί τινι</span> ( <a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0003.tlg001.perseus-grc1%3A3.82.7\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Thuc. 3, 82, 7\" data-tooltip-text=\"Tucídides, História da Guerra do Peloponeso 3.82.7 — texto grego original no Perseus Digital Library; destino validado\">Thuc. 3, 82, 7</a>; Polemo Sofista, <em>Decl.</em> 2, 17 p. 22, 1; Esopo, <em>Fab.</em> 74 P. = 128 H.; Fílon, <em>Somn.</em> 2, 211;\n<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0526.tlg001.perseus-grc1%3A17.112\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Jos., Ant. 17, 112\" data-tooltip-text=\"Flávio Josefo, Antiguidades Judaicas 17.112 — texto grego original no Perseus Digital Library; destino validado\">Jos., Ant. 17, 112</a>)\n<span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"1 Cl 33:2 v.l.\" data-tooltip-text=\"Primeira Epístola de Clemente 33.2, leitura variante\">1 Cl 33:2 v.l.</span> (o texto tem <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαλλιᾶται\" data-meanings=\"exulta|regozija-se\">ἀγαλλιᾶται</span>, q.v.). — DELG.\n</p>\n</section>\n</article><article id=\"entry-agamos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\">\n<div><h1 class=\"entry-title greek\">ἄγαμος</h1>\n<div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"greek\">ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ágamos⟧</span></div>\n</div><div class=\"source-tag\">BDAG</div>\n</header>\n<div class=\"entry-divider\"></div>\n<section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"> (Homero e outros; papiros frequentes; Ath. 33:1.)\n<strong>Homem/mulher não casado(a), solteiro(a)</strong>: de ambos os sexos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 7.8</a> (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γεγαμηκότες\" data-meanings=\"casados\">γεγαμηκότες</span> no v. 10, como\n<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0032.tlg004.perseus-grc1%3A9.7\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Xen., Symp. 9, 7\" data-tooltip-text=\"Xenofonte, Banquete 9.7 — texto grego original no Perseus Digital Library; destino validado\">Xen., Symp. 9, 7</a>). De homens, v. 32; Agr 18. De mulheres (Ésquilo, <em>Suppl.</em> 143; Hipérides 2, 12, entre outros),\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 7.34</a>; ApcPt 11:26 (Klostermann observa a restauração de Gebhardt\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ[γαμοι τὰ βρέφη τεκο]ῦσαι\" data-meanings=\"[mulheres não casadas que deram à luz] crianças\">ἄ[γαμοι τὰ βρέφη τεκο]ῦσαι</span>, mas no texto lê o advérbio <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάμως\" data-meanings=\"sem casamento|como não casada\">ἀγάμως</span>). De mulheres divorciadas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 7.11</a>. Há um uso curioso em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22.10</a> v.l. no manuscrito C. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γαμέω\" data-meanings=\"casar-se\">γαμέω</span>. <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"M-M\" data-tooltip-text=\"Moulton-Milligan, The Vocabulary of the Greek Testament\">M-M</span>. <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"TW\" data-tooltip-text=\"Theologisches Wörterbuch zum Neuen Testament\">TW</span>.\n</p>\n</section>\n</article><article id=\"entry-aganakteo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\">\n<div><h1 class=\"entry-title greek\">ἀγανακτέω</h1>\n<div class=\"entry-meta\"><span class=\"transliteration\">⟦aganaktéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div>\n</div><div class=\"source-tag\">BDAG</div>\n</header>\n<div class=\"entry-divider\"></div>\n<section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"> (Aristófanes, <em>Vesp.</em> 287 em diante;\n<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0003.tlg001.perseus-grc1%3A8.43.4\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Thuc. 8, 43, 4\" data-tooltip-text=\"Tucídides, História da Guerra do Peloponeso 8.43.4 — texto grego original no Perseus Digital Library; destino validado\">Thuc. 8, 43, 4</a>; inscrições, papiros; LXX; ApcrEzk [Epifânio 70, 70].) Futuro, 3ª sg. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγανακτήσει\" data-meanings=\"ficará indignado\">ἀγανακτήσει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 5.22</a>; 1º aoristo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγανάκτησα\" data-meanings=\"indignei-me\">ἠγανάκτησα</span> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγανάκτησις\" data-meanings=\"indignação\">ἀγανάκτησις</span>).\n<strong>Indignar-se contra aquilo que se supõe errado, irritar-se, ficar indignado, zangado</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Bel 28</a> Teod.;\n<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0526.tlg001.perseus-grc1%3A2.284\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Jos., Ant. 2, 284\" data-tooltip-text=\"Flávio Josefo, Antiguidades Judaicas 2.284 — texto grego original no Perseus Digital Library; destino validado\">Jos., Ant. 2, 284</a>):\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.8\" target=\"_blank\" rel=\"noopener noreferrer\">26.8</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10.14</a>;\n<span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"2 Cl 19:2\" data-tooltip-text=\"Segunda Epístola de Clemente 19.2\">2 Cl 19:2</span>; Ox 1224 Fgm. 2, II, 3. Com a pessoa mencionada,\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. περί τινος\" data-meanings=\"indignar-se com alguém\">ἀ. περί τινος</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10.41</a> (compare Platão, <em>Ep.</em> 7, 349d;\n<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0526.tlg001.perseus-grc1%3A14.182\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Jos., Ant. 14, 182\" data-tooltip-text=\"Flávio Josefo, Antiguidades Judaicas 14.182 — texto grego original no Perseus Digital Library; destino validado\">Jos., Ant. 14, 182</a>;\n<span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B-D-F §229, 2\" data-tooltip-text=\"Blass-Debrunner-Funk, §229, 2\">B-D-F §229, 2</span>).\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ἐπί τινι\" data-meanings=\"indignar-se com alguém|com algo\">ἀ. ἐπί τινι</span> (Lísias 1, 1; Isócrates 16, 49; PLond I, 44, 20 p. 34 [séc. II a.C.] = UPZ 8, 20\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγανακτοῦντα ἐφ’ οἷς διετελοῦντο ἐν τοιούτῳ ἱερῷ\" data-meanings=\"indignado com o que continuavam fazendo em tal santuário\">ἀγανακτοῦντα ἐφ’ οἷς διετελοῦντο ἐν τοιούτῳ ἱερῷ</span>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 12.27</a>)\n<em>com alguém</em>, GPt 4:14;\n<em>com algo</em> (<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0060.tlg001.perseus-grc1%3A4.63.3\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Diod. S. 4, 63, 3\" data-tooltip-text=\"Diodoro Sículo, Biblioteca Histórica 4.63.3 — texto grego original no Perseus Digital Library; destino validado\">Diod. S. 4, 63, 3</a>\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπὶ τῷ γεγονότι\" data-meanings=\"por causa do acontecido\">ἐπὶ τῷ γεγονότι</span>; Apiano, <em>Macedon.</em> 1, 3)\n<span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"1 Cl 56:2\" data-tooltip-text=\"Primeira Epístola de Clemente 56.2\">1 Cl 56:2</span>.\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.4</a>\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἦσαν δέ τινες ἀγανακτοῦντες πρὸς ἑαυτούς\" data-meanings=\"havia alguns indignados entre si\">ἦσαν δέ τινες ἀγανακτοῦντες πρὸς ἑαυτούς</span> é difícil; talvez <em>alguns expressavam seu desagrado uns aos outros</em> (mas em outros lugares <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πρός\" data-meanings=\"para|contra\">πρός</span> introduz aquele contra quem o desagrado é dirigido: Dio Crisóstomo 13 [7], 43\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἄρχων ἠγανάκτησε πρός με\" data-meanings=\"o governante indignou-se comigo\">ὁ ἄρχων ἠγανάκτησε πρός με</span>; Sócrates, <em>Ep.</em> 6, 7. — D lê <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ δὲ μαθηταὶ αὐτοῦ διεπονοῦντο καὶ ἔλεγον\" data-meanings=\"mas os seus discípulos estavam contrariados e diziam\">οἱ δὲ μαθηταὶ αὐτοῦ διεπονοῦντο καὶ ἔλεγον</span>). Uma razão para o desagrado é acrescentada com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅτι\" data-meanings=\"porque\">ὅτι</span> (Herodiano 3, 2, 3),\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.14</a>. — DELG. <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"M-M\" data-tooltip-text=\"Moulton-Milligan, The Vocabulary of the Greek Testament\">M-M</span>. <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Spicq\" data-tooltip-text=\"Ceslas Spicq, Notes de lexicographie néo-testamentaire\">Spicq</span>.\n</p>\n</section>\n</article><article id=\"entry-aganaktesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\">\n<div><h1 class=\"entry-title greek\">ἀγανάκτησις</h1>\n<div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aganáktēsis⟧</span><span class=\"separator\">·</span><span>substantivo</span></div>\n</div><div class=\"source-tag\">BDAG</div>\n</header>\n<div class=\"entry-divider\"></div>\n<section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"> (<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0003.tlg001.perseus-grc1%3A2.41.3\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Thuc. 2, 41, 3\" data-tooltip-text=\"Tucídides, História da Guerra do Peloponeso 2.41.3 — texto grego original no Perseus Digital Library; destino validado\">Thuc. 2, 41, 3</a> e outros; Apiano, <em>Bell. Civ.</em> 1, 10 §39; 4, 124 §521; PGrenf II, 82, 17 s.;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EST.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Est 8.12i</a> v.l.;\n<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0526.tlg004.perseus-grc1%3A4.342\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Jos., Bell. 4, 342\" data-tooltip-text=\"Flávio Josefo, Guerra Judaica 4.342 — texto grego original no Perseus Digital Library; destino validado\">Jos., Bell. 4, 342</a>.)\n<strong>Indignação</strong>,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 7.11</a>. — <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"M-M\" data-tooltip-text=\"Moulton-Milligan, The Vocabulary of the Greek Testament\">M-M</span>. <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"TW\" data-tooltip-text=\"Theologisches Wörterbuch zum Neuen Testament\">TW</span>. <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Spicq\" data-tooltip-text=\"Ceslas Spicq, Notes de lexicographie néo-testamentaire\">Spicq</span>.\n</p>\n</section>\n</article><article id=\"entry-agapao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\">\n<div><h1 class=\"entry-title greek\">ἀγαπάω</h1>\n<div class=\"entry-meta\"><span class=\"transliteration\">⟦agapáō⟧</span><span class=\"separator\">·</span><span>verbo</span></div>\n</div><div class=\"source-tag\">BDAG</div>\n</header>\n<div class=\"entry-divider\"></div>\n<section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"> Imperfeito <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγάπων\" data-meanings=\"amava\">ἠγάπων</span>; futuro <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαπήσω\" data-meanings=\"amarei\">ἀγαπήσω</span>; 1º aoristo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγάπησα\" data-meanings=\"amei\">ἠγάπησα</span>; perfeito <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγάπηκα\" data-meanings=\"tenho amado\">ἠγάπηκα</span>, particípio <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαπηκώς\" data-meanings=\"tendo amado\">ἠγαπηκώς</span>; mais-que-perfeito, 3ª sg. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαπήκει\" data-meanings=\"tinha amado\">ἠγαπήκει</span> Is. 2:25. Passivo: 1º futuro <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαπηθήσομαι\" data-meanings=\"serei amado\">ἀγαπηθήσομαι</span>; 1º aoristo, 2ª sg. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαπήθης\" data-meanings=\"foste amado\">ἠγαπήθης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.47.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 47.16</a>; particípio perfeito <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαπημένος\" data-meanings=\"amado\">ἠγαπημένος</span> (em vários sentidos, Homero em diante. — S. Tromp de Ruiter, <em>Gebruik en beteekenis van ἀγαπᾶν in de Grieksche Litteratuur</em>, 1930; C. Richardson, “Love: Gk. and Christian”, <em>JR</em> 23, 1943, 173–185).\n<span class=\"sense-number\">1.</span>\n<strong>Ter consideração calorosa e interesse por outro, estimar, ter afeição por, amar.</strong>\n<strong>a.</strong> Por seres humanos (Píndaro, Platão e outros).\n<strong>α.</strong> Para uma ampla gama de pessoas, à parte daqueles que recebem devoção especial, para os quais veja β. Com o objeto expresso:\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γυναῖκας\" data-meanings=\"esposas|mulheres\">γυναῖκας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5.25</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">28</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">33</a> (sobre a atitude apropriada do marido, compare Plutarco, <em>Mor.</em> 142e);\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3.19</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὡς ἀδελφήν\" data-meanings=\"como irmã\">ὡς ἀδελφήν</span> Hv 1, 1, 1.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν πλησίον\" data-meanings=\"o próximo\">τὸν πλησίον</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.19\" target=\"_blank\" rel=\"noopener noreferrer\">19.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.39\" target=\"_blank\" rel=\"noopener noreferrer\">22.39</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.31</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">33</a> (sobre 33b, veja Aristeneto, <em>Ep.</em> 2, 13, fim,\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φιλῶ σε ὡς ἐμαυτήν\" data-meanings=\"amo-te como a mim mesma\">φιλῶ σε ὡς ἐμαυτήν</span>);\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13.9</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5.14</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2.8</a>; B 19:5 (todas citações de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 19.18</a>); veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πλησίον\" data-meanings=\"próximo\">πλησίον</span> 2.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν ἕτερον\" data-meanings=\"o outro\">τὸν ἕτερον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13.8</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν ἀδελφόν\" data-meanings=\"o irmão\">τὸν ἀδελφόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 2.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">3.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">4.20 s.</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοὺς ἀδελφούς\" data-meanings=\"os irmãos\">τοὺς ἀδελφούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">3.14</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ τέκνα τοῦ θεοῦ\" data-meanings=\"os filhos de Deus\">τὰ τέκνα τοῦ θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">5.2</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλήλους\" data-meanings=\"uns aos outros\">ἀλλήλους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">15.12</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">17</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 3.11</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">4.7</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">11 s.</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2JN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Jo 5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 4.9</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοὺς ἀγαπῶντας\" data-meanings=\"os que amam\">τοὺς ἀγαπῶντας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.32</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ἔθνος ἡμῶν\" data-meanings=\"a nossa nação\">τὸ ἔθνος ἡμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.5</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοὺς ἐχθρούς\" data-meanings=\"os inimigos\">τοὺς ἐχθρούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.27</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.35\" target=\"_blank\" rel=\"noopener noreferrer\">35</a>; veja W. van Unnik, <em>NovT</em> 8, 1966, 284–300 e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐχθρός\" data-meanings=\"inimigo\">ἐχθρός</span> 2bβ.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. τινα ὑπὲρ τὴν ψυχήν\" data-meanings=\"amar alguém mais do que a própria vida\">ἀ. τινα ὑπὲρ τὴν ψυχήν</span>,\n<em>amar alguém mais do que a própria vida</em>, B 1:4; 4:6; 19:5; D 2:7 (compare Fílon, <em>Rer. Div. Her.</em> 42 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὑπερφυῶς ἀ.\" data-meanings=\"amar extraordinariamente\">ὑπερφυῶς ἀ.</span>; Kaibel 716, 5 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φίλους ὑπὲρ ἁτὸν [= αὑτὸν] ἐτίμα\" data-meanings=\"honrava os amigos mais do que a si mesmo\">φίλους ὑπὲρ ἁτὸν [= αὑτὸν] ἐτίμα</span>).\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ περισσοτέρως ὑμᾶς ἀγαπῶ, ἧσσον ἀγαπῶμαι;\" data-meanings=\"se vos amo mais abundantemente, sou menos amado?\">εἰ περισσοτέρως ὑμᾶς ἀγαπῶ, ἧσσον ἀγαπῶμαι;</span>,\n<em>se vos amo mais, devo ser menos amado?</em>,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 12.15</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. πολύ, ὀλίγον\" data-meanings=\"amar muito, pouco\">ἀ. πολύ, ὀλίγον</span>,\n<em>demonstrar muita ou pouca afeição</em>,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.47</a>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πλεῖον ἀγαπήσει αὐτόν\" data-meanings=\"amá-lo-á mais\">πλεῖον ἀγαπήσει αὐτόν</span> no v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.42\" target=\"_blank\" rel=\"noopener noreferrer\">42</a> (sobre o par amor–ódio, veja A. Fridrichsen, <em>Svensk Exegetisk Årsbok</em> 5, 1940, 152–162. — O sentido <em>ser grato</em> é sugerido para Lc 7.42 por H. Wood, <em>ET</em> 66, 1955, 319, seguindo J. Jeremias. Veja <a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0526.tlg004.perseus-grc1%3A1.392\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Jos., Bell. 1, 392\" data-tooltip-text=\"Flávio Josefo, Guerra Judaica 1.392 — texto grego original no Perseus Digital Library; destino validado\">Jos., Bell. 1, 392</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.114.1\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 114.1</a>). Absoluto: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡμεῖς ἀγαπῶμεν\" data-meanings=\"nós amamos\">ἡμεῖς ἀγαπῶμεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 4.19</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πᾶς ὁ ἀγαπῶν\" data-meanings=\"todo aquele que ama\">πᾶς ὁ ἀγαπῶν</span> v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">7</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ μὴ ἀγαπῶν\" data-meanings=\"aquele que não ama\">ὁ μὴ ἀγαπῶν</span> v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">8</a>. Com indicação do tipo de afeição:\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ἐν Ἰησοῦ Χρ.\" data-meanings=\"amar em Jesus Cristo\">ἀ. ἐν Ἰησοῦ Χρ.</span> IMg 6:2. Oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μισεῖν\" data-meanings=\"odiar\">μισεῖν</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 21.15–17</a>)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16.13</a>.\n<strong>β.</strong> Para destinatários transcendentes de devoção especial: a Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1.8</a>. Especialmente em João:\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.42\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">14.15</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">21</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">23 s.</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">21.15 s.</a> (sempre falado por Jesus). — Sobre a última passagem, veja A. Fridrichsen, <em>SymbOsl</em> 14, 1935, 46–49; E. McDowell, <em>RevExp</em> 32, 1935, 422–441; Goodsp., <em>Probs.</em> 116–118; J. Scott, <em>ClW</em> 39, 1945–46, 71 s.; 40, 1946–47, 60 s.; M.-E. Boismard, <em>RB</em> 54, 1947, 486 s. — <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ.\" data-meanings=\"ἀγαπάω\">ἀ.</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φιλέω\" data-meanings=\"amar|ter afeição\">φιλέω</span> podem ser usados de modo intercambiável aqui (compare a frequente alternância de sinônimos em outros lugares do mesmo capítulo [<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βόσκειν–ποιμαίνειν\" data-meanings=\"apascentar–pastorear\">βόσκειν–ποιμαίνειν</span>,\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀρνία–προβάτια\" data-meanings=\"cordeiros–ovelhas\">ἀρνία–προβάτια</span>,\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἑλκύειν–σύρειν\" data-meanings=\"puxar–arrastar\">ἑλκύειν–σύρειν</span>], mas veja K. McKay, <em>NovT</em> 27, 1985, 319–333; também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φιλέω\" data-meanings=\"amar|ter afeição\">φιλέω</span>). — A Deus (Dio Crisóstomo 11 [12], 61; Sextus 442; 444; ParJer 6:6; LXX; Fílon, <em>Post. Caini</em> 69;\n<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0526.tlg001.perseus-grc1%3A7.269\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Jos., Ant. 7, 269\" data-tooltip-text=\"Flávio Josefo, Antiguidades Judaicas 7.269 — texto grego original no Perseus Digital Library; destino validado\">Jos., Ant. 7, 269</a>; TestBenj 3:1; 4:5)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22.37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.30</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">33</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10.27</a> (todos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 6.5</a>);\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 2.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">8.3</a>. Da afeição pelo Criador, B 19:2.\n<strong>b.</strong> Da afeição de seres transcendentes.\n<strong>α.</strong> Por seres humanos comuns (Dio Crisóstomo 3, 60 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαπώμενος ὑπὸ θεῶν\" data-meanings=\"amado pelos deuses\">ἀγαπώμενος ὑπὸ θεῶν</span>; 79 [28], 13; CIG 5159 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Βρουτταρᾶτος, ὃν ἀγαπᾷ ἡ Φαρία Ἶσις\" data-meanings=\"Bruttaratos, a quem Ísis de Faros ama\">Βρουτταρᾶτος, ὃν ἀγαπᾷ ἡ Φαρία Ἶσις</span>; Norden, <em>Agn. Th.</em> 225 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὃν Ἄμμων ἀγαπᾷ\" data-meanings=\"a quem Amon ama\">ὃν Ἄμμων ἀγαπᾷ</span>; 226 [= OGI 90, 4]; veja β abaixo; LXX;\n<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0526.tlg001.perseus-grc1%3A8.173\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Jos., Ant. 8, 173\" data-tooltip-text=\"Flávio Josefo, Antiguidades Judaicas 8.173 — texto grego original no Perseus Digital Library; destino validado\">Jos., Ant. 8, 173</a>;\n<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0526.tlg001.perseus-grc1%3A8.314\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"314\" data-tooltip-text=\"Flávio Josefo, Antiguidades Judaicas 8.314 — texto grego original no Perseus Digital Library; destino validado\">314</a>; TestNapht 8:4, 10):\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.37\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8.37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">9.13</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/MAL.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ml 1.2</a>);\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 2.16</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12.6</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 3.12</a>);\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 14.21</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τηρηθήσεται\" data-meanings=\"será guardado\">τηρηθήσεται</span> P75);\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 4.10</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">19</a>;\n<span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"1 Cl 56:4\" data-tooltip-text=\"Primeira Epístola de Clemente 56.4\">1 Cl 56:4</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 3.12</a>).\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἱλαρὸν δότην\" data-meanings=\"doador alegre\">ἱλαρὸν δότην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 9.7</a>. — A afeição de Jesus pelas pessoas:\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἰ. ἠγάπησεν αὐτόν\" data-meanings=\"Jesus o amou\">Ἰ. ἠγάπησεν αὐτόν</span>,\n<em>Jesus gostou dele ou teve afeição por ele</em>,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10.21</a> (também se sugeriu <em>demonstrou afeição, acariciou-o</em>; compare <a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0032.tlg007.perseus-grc1%3A7.5.50\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Xen., Cyr. 7, 5, 50\" data-tooltip-text=\"Xenofonte, Ciropédia 7.5.50 — texto grego original no Perseus Digital Library; destino validado\">Xen., Cyr. 7, 5, 50</a>; Plutarco, <em>Pericl.</em> 152 [1, 1], entre outros). — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">15.9</a>; B 1:1. Do discípulo amado: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.26\" target=\"_blank\" rel=\"noopener noreferrer\">19.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.7\" target=\"_blank\" rel=\"noopener noreferrer\">21.7</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.20\" target=\"_blank\" rel=\"noopener noreferrer\">20</a>; veja Hdb.³ em Jo 13.23; também J. Maynard, <em>JSOR</em> 13, 1929, 155–159; Bultmann ad loc. e outros; A. Kragerud, <em>Der Lieblingsjünger im Johannesevangelium</em>, 1959; L. Johnson, <em>ET</em> 77, 1966, 157 s.; veja também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μαθητής\" data-meanings=\"discípulo\">μαθητής</span> 2bα. — Com particípio perfeito passivo (compare β):\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφοὶ ἠ. ὑπὸ τ. θεοῦ\" data-meanings=\"irmãos amados por Deus\">ἀδελφοὶ ἠ. ὑπὸ τ. θεοῦ</span> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.45.1\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 45.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.46.13\" target=\"_blank\" rel=\"noopener noreferrer\">46.13</a>)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 1.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 2.13</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγιοι καὶ ἠ.\" data-meanings=\"santos e amados\">ἅγιοι καὶ ἠ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3.12</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοῖς ἐν θεῷ πατρὶ ἠγαπημένοις\" data-meanings=\"aos amados em Deus Pai\">τοῖς ἐν θεῷ πατρὶ ἠγαπημένοις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 1</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκκλησία ἠ.\" data-meanings=\"igreja amada\">ἐκκλησία ἠ.</span> ITr ins; IRo ins. — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9.25</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/HOS.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Os 2.25</a> v.l.).\n<strong>β.</strong> Para outros seres transcendentes: o amor de Deus por Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3.35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">10.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">17.26</a>, desde antes da criação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">17.24</a>. Aqui pertence também o particípio perfeito passivo, <em>aquele amado por Deus</em> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.32.15\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 32.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.33.5\" target=\"_blank\" rel=\"noopener noreferrer\">33.5</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.33.26\" target=\"_blank\" rel=\"noopener noreferrer\">26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.44.2\" target=\"_blank\" rel=\"noopener noreferrer\">Is 44.2</a>) como designação de Jesus (compare ParJer 3:11; AscIs 3:4; TestAbr A 1 p. 78, 6 [Stone p. 4] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀβραὰμ τὸν ἠ. μου φίλον\" data-meanings=\"Abraão, meu amado amigo\">Ἀβραὰμ τὸν ἠ. μου φίλον</span>; OGI 90, 4 [séc. II a.C.], um rei egípcio é <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαπημένος ὑπό τοῦ Φθᾶ\" data-meanings=\"amado por Ptá\">ἠγαπημένος ὑπό τοῦ Φθᾶ</span>; Mitt.-Wilck. I/2, 109, 12 [séc. III a.C.], um rei <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαπημένος ὑπὸ τ. Ἴσιδος\" data-meanings=\"amado por Ísis\">ἠγαπημένος ὑπὸ τ. Ἴσιδος</span>)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1.6</a>; B 3:6; 4:3, 8.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαπημένος παῖς αὐτοῦ\" data-meanings=\"seu servo amado\">ἠγαπημένος παῖς αὐτοῦ</span> 1 Cl 59:2 s.;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"υἱὸς ἠ.\" data-meanings=\"filho amado\">υἱὸς ἠ.</span> Hs 9, 12, 5. De Jerusalém <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν πόλιν τὴν ἠ.\" data-meanings=\"a cidade amada\">τὴν πόλιν τὴν ἠ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.24.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 24.11</a>)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 20.9</a>. — Veja a literatura em <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φιλέω\" data-meanings=\"amar|ter afeição\">φιλέω</span> 1a. — O amor de Jesus por Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 14.31</a>.\n<span class=\"sense-number\">2.</span>\n<strong>Ter alta estima ou satisfação por algo, ter prazer em.</strong> (Esopo, <em>Fab.</em> 156 P.) — Apiano, <em>Mithrid.</em> 57 §230\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ προτεινόμενα\" data-meanings=\"os termos propostos\">τὰ προτεινόμενα</span> = os termos oferecidos. PsSol 14:6 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡμέραν ἐν μετοχῇ ἁμαρτίας αὐτῶν\" data-meanings=\"dia de participação no pecado deles\">ἡμέραν ἐν μετοχῇ ἁμαρτίας αὐτῶν</span>. Também <strong>esforçar-se por, aspirar a algo</strong> (Teopompo [séc. IV a.C.]: 115 Fgm. 124 Jac. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τιμήν\" data-meanings=\"honra\">τιμήν</span>;\n<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0060.tlg001.perseus-grc1%3A11.46.2\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Diod. S. 11, 46, 2\" data-tooltip-text=\"Diodoro Sículo, Biblioteca Histórica 11.46.2 — texto grego original no Perseus Digital Library; destino validado\">Diod. S. 11, 46, 2</a> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τ. πλοῦτον\" data-meanings=\"a riqueza\">τ. πλοῦτον</span>; Apiano, <em>Bell. Civ.</em> 1, 49 §215, cidadania; SIG 1268 I, 9 [séc. III a.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φιλίαν ἀγάπα\" data-meanings=\"estima a amizade\">φιλίαν ἀγάπα</span>; papiro do início do período ptolemaico em W. Crönert, <em>NGG</em> 1922, 31;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.39.17\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 39.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 3.26</a>):\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν πρωτοκαθεδρίαν καὶ τοὺς ἀσπασμούς\" data-meanings=\"os primeiros assentos e as saudações\">τὴν πρωτοκαθεδρίαν καὶ τοὺς ἀσπασμούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.43</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μισθὸν ἀδικίας\" data-meanings=\"salário da injustiça\">μισθὸν ἀδικίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2.15</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν κόσμον\" data-meanings=\"o mundo\">τὸν κόσμον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 2.15</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν νῦν αἰῶνα\" data-meanings=\"a era presente\">τὸν νῦν αἰῶνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4.10</a>; Pol 9:2.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δικαιοσύνην\" data-meanings=\"justiça\">δικαιοσύνην</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 1.1</a>; Orígenes, <em>C. Cels.</em> 6, 79, 22)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1.9</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.44.8\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 44.8</a>).\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σεμνότητα\" data-meanings=\"dignidade|respeitabilidade\">σεμνότητα</span> Hm 5, 2, 8.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν ἀλήθειαν\" data-meanings=\"a verdade\">τὴν ἀλήθειαν</span> (<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0526.tlg003.perseus-grc1%3A2.296\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Jos., C. Ap. 2, 296\" data-tooltip-text=\"Flávio Josefo, Contra Apião 2.296 — texto grego original no Perseus Digital Library; destino validado\">Jos., C. Ap. 2, 296</a>; TestReub 3:9) 1 Cl 18:6 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.50.8\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 50.8</a>); Hm 3:1. Oposto: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ψεύδη\" data-meanings=\"amar mentiras\">ἀ. ψεύδη</span> B 20:2.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅρκον ψευδῆ\" data-meanings=\"juramento falso\">ὅρκον ψευδῆ</span> 2:8 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ZEC.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">Zc 8.17</a>).\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μᾶλλον τὸ σκότος ἢ τὸ φῶς\" data-meanings=\"mais as trevas do que a luz\">μᾶλλον τὸ σκότος ἢ τὸ φῶς</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3.19</a> (sobre <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγ. μᾶλλον\" data-meanings=\"amar mais\">ἀγ. μᾶλλον</span> com acusativo, compare\n<a class=\"biblio-ref reference-link tooltip-trigger\" href=\"https://www.perseus.tufts.edu/hopper/text?doc=urn%3Acts%3AgreekLit%3Atlg0526.tlg001.perseus-grc1%3A5.350\" target=\"_blank\" rel=\"noopener noreferrer\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Jos., Ant. 5, 350\" data-tooltip-text=\"Flávio Josefo, Antiguidades Judaicas 5.350 — texto grego original no Perseus Digital Library; destino validado\">Jos., Ant. 5, 350</a> e veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μᾶλλον\" data-meanings=\"mais\">μᾶλλον</span> 3c);\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. τὴν δόξαν τ. ἀνθρώπων μᾶλλον ἤπερ τ. δ. τοῦ θεοῦ\" data-meanings=\"amar a glória dos homens mais do que a glória de Deus\">ἀ. τὴν δόξαν τ. ἀνθρώπων μᾶλλον ἤπερ τ. δ. τοῦ θεοῦ</span>,\n<em>valorizar a aprovação dos seres humanos mais do que a de Deus</em>,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.43\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12.43</a> (compare Platão, <em>Phdr.</em> 257e).\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ζωήν\" data-meanings=\"vida\">ζωήν</span>, <em>desfrutar a vida</em> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 4.12</a>)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 3.10</a>; também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν ψυχήν\" data-meanings=\"a vida|a alma\">τὴν ψυχήν</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.30.23\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 30.23</a> v.l.)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12.11</a>. — Daí <strong>ansiar por algo</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.39.17\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 39.17</a>)\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν ἐπιφάνειαν αὐτοῦ\" data-meanings=\"a sua manifestação\">τὴν ἐπιφάνειαν αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4.8</a>. Com infinitivo em seguida, <strong>desejar</strong> (Antonino Liberal 40, 1 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγάπησεν ἀεὶ παρθένος εἶναι\" data-meanings=\"desejou ser sempre virgem\">ἠγάπησεν ἀεὶ παρθένος εἶναι</span>);\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ἡμέρας ἰδεῖν ἀγαθάς\" data-meanings=\"desejar ver dias bons\">ἀ. ἡμέρας ἰδεῖν ἀγαθάς</span>\n<span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"1 Cl 22:2\" data-tooltip-text=\"Primeira Epístola de Clemente 22.2\">1 Cl 22:2</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.33.13\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 33.13</a>);\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ παθεῖν\" data-meanings=\"sofrer\">τὸ παθεῖν</span>, <em>desejar o martírio</em>, ITr 4:2. — <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάπην ἀ.\" data-meanings=\"amar amor|demonstrar amor\">ἀγάπην ἀ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2SA.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Sm 13.15</a>), <strong>demonstrar amor</strong>,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 17.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2.4</a>;\n<strong>demonstrar admiração</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ δεσμά\" data-meanings=\"pelas correntes|pelos grilhões\">τὰ δεσμά</span>, por minhas correntes, isto é, não se envergonhar delas, IPol 2:3 (não “beijar”; até agora não há evidência desse sentido de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ.\" data-meanings=\"ἀγαπάω\">ἀ.</span>). — Em ISm 7:1, o contexto parece exigir para <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ.\" data-meanings=\"ἀγαπάω\">ἀ.</span> o sentido\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάπην ποιεῖν\" data-meanings=\"realizar uma refeição de amor\">ἀγάπην ποιεῖν</span> (8:2) = <em>realizar uma ágape</em>, mas até agora esse sentido não pode ser confirmado lexicalmente. Como o substantivo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάπη\" data-meanings=\"amor|ágape\">ἀγάπη</span> é usado absolutamente em 6:2 no sentido “preocupação por” alguém, pode ser que <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαπᾶν\" data-meanings=\"amar\">ἀγαπᾶν</span> em 7:1 se refira a atos de bondade.\n<span class=\"sense-number\">3.</span>\n<strong>Praticar/expressar amor, provar o próprio amor</strong>,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.1</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">34</a> (talvez uma alusão à ágape ou refeição de amor; veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάπη\" data-meanings=\"amor|ágape\">ἀγάπη</span> 2). Absoluto, com indicação dos meios:\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μὴ ἀγαπῶμεν λόγῳ μηδὲ τῇ γλώσσῃ ἀλλὰ ἐν ἔργῳ\" data-meanings=\"não amemos de palavra nem de língua, mas em ação\">μὴ ἀγαπῶμεν λόγῳ μηδὲ τῇ γλώσσῃ ἀλλὰ ἐν ἔργῳ</span>,\n<em>mostremos nosso amor com ações, bem como com palavra ou língua</em> (TestGad 6:1 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαπήσατε ἀλλήλους ἐν ἔργῳ\" data-meanings=\"amai-vos uns aos outros em ação\">ἀγαπήσατε ἀλλήλους ἐν ἔργῳ</span>)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 3.18</a>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. τῷ στόματι\" data-meanings=\"amar com a boca\">ἀ. τῷ στόματι</span>\n<span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"1 Cl 15:4\" data-tooltip-text=\"Primeira Epístola de Clemente 15.4\">1 Cl 15:4</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.77.36\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 77.36</a> Swete; ed. Rahlfs 1931 v.l.). — R. Joly, <em>Le vocabulaire chrétien de l’amour est-il original?</em>, 1968. — <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B. 1110\" data-tooltip-text=\"Referência abreviada do BDAG: B. 1110\">B. 1110</span>. DELG. <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"M-M\" data-tooltip-text=\"Moulton-Milligan, The Vocabulary of the Greek Testament\">M-M</span>. <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"TW\" data-tooltip-text=\"Theologisches Wörterbuch zum Neuen Testament\">TW</span>. <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Spicq\" data-tooltip-text=\"Ceslas Spicq, Notes de lexicographie néo-testamentaire\">Spicq</span>. <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"Sv.\" data-tooltip-text=\"Referência abreviada conforme BDAG\">Sv.</span>.\n</p>\n</section>\n</article>"};
